        </div>

        {/* Khung cuộn ngang chứa cả Bảng bên trái + Biểu đồ bên phải */}
        <div className="overflow-x-auto relative max-h-[700px] overflow-y-auto">
          <div className="flex" style={{ width: `${620 + ganttWidth}px`, minWidth: '100%' }}>

            {/* ================= KHUNG TRÁI: BẢNG DỮ LIỆU CÔNG VIỆC (ĐÓNG BĂNG FREEZE) ================= */}
            <div className="w-[620px] flex-shrink-0 sticky left-0 z-30 bg-white dark:bg-slate-900 border-r-2 border-slate-300 dark:border-slate-700 shadow-lg">

              {/* Header Bảng Bên Trái */}
