                className="sticky top-0 z-40 bg-slate-100 dark:bg-slate-800 border-b border-slate-200 dark:border-slate-700 flex items-center text-xs font-bold text-slate-700 dark:text-slate-200 uppercase tracking-wider"
                style={{ height: `${HEADER_HEIGHT}px` }}
              >
                <div className="w-12 text-center py-2 px-1 border-r border-slate-200 dark:border-slate-700">STT</div>
                <div className="flex-1 py-2 px-3 border-r border-slate-200 dark:border-slate-700">CÔNG VIỆC TRONG DỰ ÁN</div>
                <div className="w-14 text-center py-2 px-1 border-r border-slate-200 dark:border-slate-700">ĐV</div>
                <div className="w-20 text-center py-2 px-1 border-r border-slate-200 dark:border-slate-700">BẮT ĐẦU</div>
                <div className="w-20 text-center py-2 px-1 border-r border-slate-200 dark:border-slate-700">KẾT THÚC</div>
                <div className="w-14 text-center py-2 px-1 border-r border-slate-200 dark:border-slate-700">NGÀY</div>
