                          : isHoliday
                          ? 'bg-amber-500/5 text-amber-800 dark:text-amber-200'
                          : 'text-slate-700 dark:text-slate-300'
                      }`}
                      style={{ height: `${ROW_HEIGHT}px` }}
                    >
                      {/* Cột STT */}
                      <div className="w-12 text-center py-1 px-1 font-mono font-semibold border-r border-slate-100 dark:border-slate-800 truncate">
                        {item.code}
                      </div>

                      {/* Cột Tên Công Việc (Có thụt dòng theo cấp A -> A1 -> A1.1) */}
                      <div
                        className="flex-1 py-1 px-3 border-r border-slate-100 dark:border-slate-800 truncate flex items-center gap-1.5"
                        style={{
                          paddingLeft: item.code.includes('.')
                            ? '28px'
                            : item.code.length > 1
                            ? '18px'
                            : '12px'
                        }}
                      >
                        {isGroup && (
                          <span
                            className="w-2.5 h-2.5 rounded-full flex-shrink-0"
                            style={{ backgroundColor: item.color }}
                          />
                        )}
                        <span className="truncate" title={item.title}>
                          {item.title}
                        </span>
                      </div>

                      {/* Cột ĐV (Đơn vị thực hiện: TK, PL, CDT, NT, VN) */}
                      <div className="w-14 text-center py-1 px-1 font-mono font-bold text-[11px] border-r border-slate-100 dark:border-slate-800 text-sky-600 dark:text-sky-400">
                        {item.unit}
                      </div>

                      {/* Cột Bắt Đầu */}
                      <div className="w-20 text-center py-1 px-1 text-[11px] border-r border-slate-100 dark:border-slate-800 text-slate-500">
                        {item.startDate.slice(5).replace('-', '/')}
