                      {/* Cột Ngày (Duration) */}
                      <div className="w-14 text-center py-1 px-1 font-bold text-[11px] border-r border-slate-100 dark:border-slate-800">
                        {item.days}
                      </div>

                      {/* Cột Ghi Chú / GATE */}
                      <div className="w-24 py-1 px-2 text-[10px] text-slate-400 truncate border-r border-slate-100 dark:border-slate-800" title={item.notes}>
                        {item.notes || '-'}
