              </div>

            </div>

            {/* ================= KHUNG PHẢI: BIỂU ĐỒ GANTT NẰM BÊN PHẢI (SVG TƯƠNG TÁC) ================= */}
            <div className="relative flex-1 bg-slate-50/50 dark:bg-slate-950/50" style={{ width: `${ganttWidth}px` }}>

              {/* Header Tháng & Tuần của Biểu Đồ Gantt */}
              <div
                className="sticky top-0 z-20 bg-slate-100 dark:bg-slate-800 border-b border-slate-200 dark:border-slate-700 flex"
                style={{ height: `${HEADER_HEIGHT}px`, width: `${ganttWidth}px` }}
              >
                {monthColumns.map((col, idx) => (
                  <div
                    key={idx}
                    className="border-r border-slate-200 dark:border-slate-700 flex flex-col justify-center items-center px-1 text-center select-none"
                    style={{ width: `${col.width}px` }}
                  >
                    <span className="font-extrabold text-xs text-sky-600 dark:text-sky-400">
                      {col.label}
                    </span>
                    <span className="text-[10px] text-slate-400 font-mono">
                      Tuần 1-4
                    </span>
                  </div>
                ))}
              </div>

              {/* Lưới Nền (Grid Lines) & Dải Ruy-băng Nghỉ Lễ Việt Nam */}
              <div className="absolute inset-0 top-[50px] pointer-events-none flex" style={{ width: `${ganttWidth}px` }}>
                {monthColumns.map((col, idx) => (
                  <div
                    key={idx}
                    className="border-r border-slate-200/40 dark:border-slate-800/40 h-full"
                    style={{ width: `${col.width}px` }}
                  />
                ))}
              </div>

              {/* KHUNG VẼ THANH GANTT & ĐƯỜNG MŨI TÊN FS BẰNG SVG CHÍNH XÁC */}
              <svg
                width={ganttWidth}
                height={HEADER_HEIGHT + filteredGanttItems.length * ROW_HEIGHT + 20}
                className="relative z-10"
              >
                <defs>
                  {/* Mũi tên đầu đường phụ thuộc Finish-to-Start */}
                  <marker
                    id="arrowhead"
                    markerWidth="8"
                    markerHeight="8"
                    refX="6"
                    refY="3"
                    orient="auto"
                  >
                    <path d="M0,0 L0,6 L6,3 z" fill="#0284c7" />
                  </marker>

                  {/* Gradient cho các thanh bar */}
                  <linearGradient id="grad-sky" x1="0%" y1="0%" x2="100%" y2="0%">
                    <stop offset="0%" stopColor="#0284c7" />
                    <stop offset="100%" stopColor="#38bdf8" />
                  </linearGradient>
                  <linearGradient id="grad-amber" x1="0%" y1="0%" x2="100%" y2="0%">
                    <stop offset="0%" stopColor="#d97706" />
                    <stop offset="100%" stopColor="#fbbf24" />
                  </linearGradient>
                  <linearGradient id="grad-red" x1="0%" y1="0%" x2="100%" y2="0%">
                    <stop offset="0%" stopColor="#b91c1c" />
                    <stop offset="100%" stopColor="#ef4444" />
                  </linearGradient>
                  <linearGradient id="grad-green" x1="0%" y1="0%" x2="100%" y2="0%">
                    <stop offset="0%" stopColor="#15803d" />
                    <stop offset="100%" stopColor="#22c55e" />
                  </linearGradient>
                </defs>

                {/* 1. Vẽ các đường kẻ ngang phân tách từng dòng */}
                {filteredGanttItems.map((_, idx) => (
                  <line
                    key={idx}
                    x1="0"
                    y1={HEADER_HEIGHT + idx * ROW_HEIGHT}
                    x2={ganttWidth}
                    y2={HEADER_HEIGHT + idx * ROW_HEIGHT}
                    stroke="#e2e8f0"
                    strokeWidth="1"
                    className="dark:stroke-slate-800/60"
                  />
                ))}

                {/* 2. HIỂN THỊ MŨI TÊN KẺ XUỐNG CÔNG VIỆC TIẾP THEO TRONG DỰ ÁN (FS Dependency) */}
                {dependencyLines.map((line) => (
                  <path
                    key={line.key}
                    d={line.path}
                    fill="none"
                    stroke="#0284c7"
                    strokeWidth="1.8"
                    strokeDasharray="4 2"
                    markerEnd="url(#arrowhead)"
                    className="transition-all hover:stroke-sky-400"
                  />
                ))}

                {/* 3. Vẽ các thanh tiến độ Gantt Bar */}
                {filteredGanttItems.map((item) => {
                  const coord = taskCoordinates[item.id];
                  if (!coord) return null;

                  const isGroup = item.isGroup;
                  const isHoliday = item.status === 'holiday';

                  // Chọn màu gradient
                  let fillColor = 'url(#grad-sky)';
                  if (item.color === '#eab308' || isHoliday) fillColor = 'url(#grad-amber)';
                  if (item.color === '#dc2626') fillColor = 'url(#grad-red)';
                  if (item.color === '#16a34a') fillColor = 'url(#grad-green)';

                  return (
                    <g key={item.id} className="cursor-pointer group">

                      {/* Dải ruy băng mờ kéo ngang cho ngày lễ */}
                      {isHoliday && (
                        <rect
                          x={coord.x}
                          y={HEADER_HEIGHT}
                          width={coord.width}
                          height={filteredGanttItems.length * ROW_HEIGHT}
                          fill="#fef08a"
                          fillOpacity="0.12"
                        />
                      )}

                      {/* Thanh Gantt chính */}
                      <rect
                        x={coord.x}
                        y={coord.y}
                        width={coord.width}
                        height={coord.height}
                        rx="8"
                        ry="8"
                        fill={fillColor}
                        className="transition-all hover:opacity-90 shadow-sm"
                        filter="drop-shadow(0 2px 4px rgba(0,0,0,0.12))"
                      />

                      {/* Nhãn trên thanh hoặc cạnh thanh: Tên người đảm nhận, thời gian, tăng ca */}
                      <text
                        x={coord.endX + 8}
                        y={coord.centerY + 4}
                        fill="#64748b"
                        fontSize="11"
                        fontWeight="600"
                        className="dark:fill-slate-300 select-none pointer-events-none"
                      >
                        {item.assignee} ({item.days} ngày)
                        {item.overtimeHours && (
                          <tspan fill="#f59e0b" fontWeight="bold"> [+{item.overtimeHours}h OT]</tspan>
                        )}
                        {item.speed === 'early' && (
                          <tspan fill="#10b981"> [Sớm]</tspan>
                        )}
                        {item.speed === 'delayed' && (
                          <tspan fill="#ef4444" fontWeight="bold"> [Chậm]</tspan>
                        )}
                      </text>

                      {/* Chữ hiển thị bên trong thanh nếu đủ rộng */}
                      {coord.width > 60 && (
                        <text
                          x={coord.x + 8}
                          y={coord.centerY + 4}
                          fill="#ffffff"
                          fontSize="10"
                          fontWeight="bold"
                          className="select-none pointer-events-none truncate"
                        >
                          {item.code} {coord.width > 120 ? `- ${item.days}d` : ''}
                        </text>
                      )}

                    </g>
                  );
                })}

              </svg>

            </div>

          </div>
        </div>

      </div>

      {/* MODAL 1: THÊM CÔNG VIỆC VÀO DỰ ÁN */}
      {showAddTaskModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fade-in">
