import { readDb, writeDb } from '../models/db.js';

/**
 * Controller Quản Lý Nhân Sự (HR)
 * Quản lý danh sách nhân sự, trạng thái có mặt tại công trường (On-site),
 * và số lượng task được giao cho từng người (đồng bộ 2 chiều với Gantt & Task).
 */

// Lấy danh sách toàn bộ nhân sự kèm số task đang phụ trách
export function getEmployees(req, res) {
  const db = readDb();
  const tasks = db.tasks || [];
  const ganttItems = db.ganttItems || [];
  const overtimes = db.overtimes || [];

  // Tính số lượng task và giờ OT cho từng nhân viên
  const employeesWithStats = db.employees.map(emp => {
    const empNameNorm = (emp.name || '').trim().toLowerCase();

    // 1. Lấy từ danh sách db.tasks
    const assignedTasks = tasks.filter(t =>
      t.employeeId === emp.id ||
      (t.employeeName && t.employeeName.trim().toLowerCase() === empNameNorm)
    );

    // 2. Đồng bộ thêm từ ganttItems nếu có task giao theo tên người đảm nhận
    ganttItems.forEach(g => {
      if (g.assignee && g.assignee.trim().toLowerCase() === empNameNorm && !g.isGroup) {
        if (!assignedTasks.some(t => t.title === g.title || t.ganttId === g.id || t.id === g.id)) {
          assignedTasks.push({
            id: g.id,
            title: g.title,
            status: g.status || 'in_progress',
            speedStatus: g.speed || 'on_time'
          });
        }
      }
    });

    const empOvertimes = overtimes.filter(o =>
      o.employeeId === emp.id ||
      (o.employeeName && o.employeeName.trim().toLowerCase() === empNameNorm)
    );
    const totalOtHours = empOvertimes.reduce((sum, o) => sum + (Number(o.hours) || 0), 0);

    return {
      ...emp,
      taskCount: assignedTasks.length,
      tasks: assignedTasks.map(t => ({ id: t.id, title: t.title, status: t.status })),
      totalOtHours: Math.round(totalOtHours * 10) / 10
    };
  });

  return res.json({
    success: true,
    data: employeesWithStats,
    meta: {
      total: employeesWithStats.length,
      onSiteCount: employeesWithStats.filter(e => e.isOnSite).length,
      standardHoursPerPerson: 8
    }
  });
}

// Thêm nhân sự mới
export function createEmployee(req, res) {
  const db = readDb();
  const { name, title, team, phone, email, standardHours } = req.body;

  if (!name || !title) {
    return res.status(400).json({ success: false, message: 'Vui lòng nhập họ tên và chức danh' });
  }

  const newEmployee = {
    id: `emp-${Date.now()}`,
    code: `NV-${String(db.employees.length + 1).padStart(3, '0')}`,
    name,
    title,
    team: team || 'Ban Quản Lý',
    phone: phone || 'Đang cập nhật',
    email: email || '',
    standardHours: Number(standardHours) || 8,
    isOnSite: true,
    checkInTime: new Date().toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' }),
    avatar: `https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=120&auto=format&fit=crop&q=80`
  };

  db.employees.push(newEmployee);
  writeDb(db);

  return res.status(201).json({
    success: true,
    message: 'Tạo nhân sự mới thành công',
    data: newEmployee
  });
}

// Chuyển đổi trạng thái có mặt tại công trường (Vào / Ra ca)
export function toggleOnSite(req, res) {
  const db = readDb();
  const { id } = req.params;

  const emp = db.employees.find(e => e.id === id);
  if (!emp) {
    return res.status(404).json({ success: false, message: 'Không tìm thấy nhân sự' });
  }

  emp.isOnSite = !emp.isOnSite;
  if (emp.isOnSite) {
    emp.checkInTime = new Date().toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' });
  } else {
    emp.checkInTime = null;
  }

  writeDb(db);

  return res.json({
    success: true,
    message: `Đã cập nhật trạng thái của ${emp.name}: ${emp.isOnSite ? 'Có mặt tại công trường' : 'Đã rời công trường'}`,
    data: emp
  });
}

// Xóa nhân sự
export function deleteEmployee(req, res) {
  const db = readDb();
  const { id } = req.params;

  const index = db.employees.findIndex(e => e.id === id);
  if (index === -1) {
    return res.status(404).json({ success: false, message: 'Không tìm thấy nhân sự' });
  }

  const removed = db.employees.splice(index, 1);
  writeDb(db);

  return res.json({
    success: true,
    message: `Đã xóa nhân sự ${removed[0].name}`,
    data: removed[0]
  });
}

import { readDb, writeDb } from '../models/db.js';

/**
 * Controller Quản Lý Tiến Độ Dự Án & Biểu Đồ Gantt Công Trường
 * Xử lý dữ liệu WBS (Phân rã công việc), mốc thời gian, liên kết phụ thuộc FS,
 * và thuật toán sắp xếp phân tầng WBS tự động (VD: A1.3 tự động nằm sau A1.2).
 * ĐỒNG BỘ 2 CHIỀU VỚI DANH SÁCH NHIỆM VỤ (TASKS) VÀ NHÂN SỰ (HR).
 */

// Thứ tự ưu tiên của các khối giai đoạn lớn theo mẫu tiến độ công trình
const MAJOR_PHASE_ORDER = ['A', 'L', 'B', 'C', 'D', 'E', 'F', 'G'];

/**
 * Phân tích mã WBS (VD: 'A1.3' -> { majorIdx: 0, segments: [1, 3] })
 */
export function parseWbsCode(code) {
  if (!code) return { majorIdx: 999, segments: [] };
  const cleaned = String(code).trim();
  const match = cleaned.match(/^([A-Za-z]+)(.*)$/);
  if (!match) return { majorIdx: 999, segments: [cleaned] };

  const letter = match[1].toUpperCase();
  const rest = match[2];

  let majorIdx = MAJOR_PHASE_ORDER.indexOf(letter);
  if (majorIdx === -1) majorIdx = 100 + letter.charCodeAt(0);

  const segments = rest
    ? rest
        .split('.')
        .map(s => {
          const num = parseInt(s, 10);
          return isNaN(num) ? s : num;
        })
    : [];

  return { majorIdx, segments };
}

/**
 * So sánh 2 mã WBS để sắp xếp đúng thứ tự cây phân tầng
 * Ví dụ: A1 < A1.1 < A1.2 < A1.3 < A2 < A2.1 < L < B
 */
export function compareWbs(codeA, codeB) {
  const pa = parseWbsCode(codeA);
  const pb = parseWbsCode(codeB);

  // So sánh nhóm giai đoạn lớn trước (A trước L, L trước B, B trước C)
  if (pa.majorIdx !== pb.majorIdx) {
    return pa.majorIdx - pb.majorIdx;
  }

  // So sánh từng cấp số con bên trong
  const maxLen = Math.max(pa.segments.length, pb.segments.length);
  for (let i = 0; i < maxLen; i++) {
    const sa = pa.segments[i];
    const sb = pb.segments[i];

    if (sa === undefined) return -1; // Cấp cha ngắn hơn đứng trước (A1 đứng trước A1.1)
    if (sb === undefined) return 1;

    if (typeof sa === 'number' && typeof sb === 'number') {
      if (sa !== sb) return sa - sb;
    } else {
      const cmp = String(sa).localeCompare(String(sb));
      if (cmp !== 0) return cmp;
    }
  }

  return 0;
}

// Lấy danh sách dự án
export function getProjects(req, res) {
  const db = readDb();
  return res.json({
    success: true,
    data: db.projects || []
  });
}

// Tạo dự án mới
export function createProject(req, res) {
  const db = readDb();
  const { name, code, description, location, manager, startDate, endDate } = req.body;

  if (!name) {
    return res.status(400).json({ success: false, message: 'Vui lòng nhập tên dự án' });
  }

  const newProject = {
    id: `proj-${Date.now()}`,
    code: code || `APS-${new Date().getFullYear()}-${db.projects.length + 1}`,
    name,
    description: description || '',
    location: location || 'Hà Nội',
    manager: manager || 'Trần Quốc Hưng',
    startDate: startDate || new Date().toISOString().split('T')[0],
    endDate: endDate || '2027-12-31',
    status: 'planning',
    progress: 0
  };

  db.projects.push(newProject);
  writeDb(db);

  return res.status(201).json({
    success: true,
    message: 'Tạo dự án mới thành công',
    data: newProject
  });
}

// Lấy danh sách hạng mục cho biểu đồ Gantt
export function getGanttItems(req, res) {
  const db = readDb();
  return res.json({
    success: true,
    data: db.ganttItems || []
  });
}

// Thêm mới công việc vào biểu đồ Gantt dự án
// TỰ ĐỘNG CHÈN ĐÚNG VỊ TRÍ PHÂN TẦNG WBS (VD: A1.3 NẰM SAU A1.2) VÀ ĐỒNG BỘ SANG TASKS
export function createGanttItem(req, res) {
  const db = readDb();
  const {
    code,
    title,
    isGroup,
    unit,
    startDate,
    endDate,
    days,
    assignee,
    notes,
    color,
    dependencies,
    speed,
    insertAfterId // Tùy chọn: người dùng chỉ định chèn cụ thể sau công việc nào
  } = req.body;

  if (!title || !startDate || !endDate) {
    return res.status(400).json({ success: false, message: 'Vui lòng nhập đầy đủ tên công việc, ngày bắt đầu và ngày kết thúc' });
  }

  const start = new Date(startDate);
  const end = new Date(endDate);
  const calculatedDays = days ? Number(days) : Math.max(1, Math.round((end - start) / (1000 * 60 * 60 * 24)) + 1);

  const formattedCode = code ? String(code).trim() : `T${db.ganttItems.length + 1}`;
  const newGanttId = `G-${Date.now()}`;

  // === 1. TÍNH TOÁN VỊ TRÍ CHÈN WBS ===
  let insertIdx = -1;
  if (insertAfterId) {
    insertIdx = db.ganttItems.findIndex(g => g.id === insertAfterId);
  } else {
    for (let i = 0; i < db.ganttItems.length; i++) {
      if (compareWbs(db.ganttItems[i].code, formattedCode) < 0) {
        insertIdx = i;
      }
    }
  }

  // === 2. TỰ ĐỘNG TẠO ĐƯỜNG MŨI TÊN LIÊN KẾT FS NỐI XUỐNG ===
  let autoDependencies = Array.isArray(dependencies) ? [...dependencies] : [];
  if (autoDependencies.length === 0 && !isGroup) {
    // Tự động liên kết tới công việc đứng ngay trước đó để vẽ đường nối xuống
    if (insertIdx >= 0 && db.ganttItems[insertIdx]) {
      autoDependencies.push(db.ganttItems[insertIdx].id);
    }
  }

  const newItem = {
    id: newGanttId,
    code: formattedCode,
    title,
    isGroup: Boolean(isGroup),
    color: color || '#0284c7',
    unit: unit || 'TK',
    startDate,
    endDate,
    days: calculatedDays,
    assignee: assignee || 'Trần Quốc Hưng',
    notes: notes || '',
    status: 'in_progress',
    speed: speed || 'on_time',
    progress: 0,
    dependencies: autoDependencies
  };

  // Chèn vào mảng ganttItems
  if (insertIdx === -1) {
    db.ganttItems.unshift(newItem);
  } else {
    db.ganttItems.splice(insertIdx + 1, 0, newItem);
  }

  // === 3. ĐỒNG BỘ SANG MỤC 1 (PHÂN CÔNG CÔNG VIỆC) & TRANG NHÂN SỰ ===
  if (!isGroup) {
    // Tìm nhân sự tương ứng
    const empNameNorm = (newItem.assignee || '').trim().toLowerCase();
    const emp = db.employees.find(e => e.name.trim().toLowerCase() === empNameNorm) || db.employees[0];

    // Xác định tên giai đoạn (Phase)
    let phaseName = 'A. THIẾT KẾ XÂY DỰNG';
    const upperCode = newItem.code.toUpperCase();
    if (upperCode.startsWith('B')) phaseName = 'B. XIN PHÉP / PHÁP LÝ';
    else if (upperCode.startsWith('C')) phaseName = 'C. MỜI THẦU THI CÔNG';
    else if (upperCode.startsWith('L')) phaseName = 'L. NGHỈ LỄ VIỆT NAM';

    const matchedTask = {
      id: `task-${Date.now()}`,
      ganttId: newItem.id,
      projectId: 'proj-1',
      projectName: 'DỰ ÁN XÂY DỰNG TRUNG TÂM CÔNG NGHỆ APS VIỆT NAM',
      phase: phaseName,
      title: newItem.title,
      code: newItem.code,
      employeeId: emp ? emp.id : 'emp-1',
      employeeName: emp ? emp.name : newItem.assignee,
      startDate: newItem.startDate,
      endDate: newItem.endDate,
      estimatedHours: newItem.days * 8,
      estimatedDays: newItem.days,
      status: 'in_progress',
      speedStatus: newItem.speed || 'on_time',
      priority: 'high',
      progress: 0,
      notes: newItem.notes || ''
    };

    // Đẩy vào db.tasks
    if (!db.tasks) db.tasks = [];
    db.tasks.push(matchedTask);
  }

  writeDb(db);

  return res.status(201).json({
    success: true,
    message: `Đã thêm công việc "${newItem.title}" (${newItem.code}) vào đúng vị trí tiến độ và đồng bộ sang danh sách nhiệm vụ`,
    data: newItem
  });
}

// Di chuyển công việc lên / xuống (Reorder)
export function moveGanttItem(req, res) {
  const db = readDb();
  const { id } = req.params;
  const { direction } = req.body; // 'up' hoặc 'down'

  const index = db.ganttItems.findIndex(g => g.id === id);
  if (index === -1) {
    return res.status(404).json({ success: false, message: 'Không tìm thấy công việc' });
  }

  const targetIndex = direction === 'up' ? index - 1 : index + 1;
  if (targetIndex < 0 || targetIndex >= db.ganttItems.length) {
    return res.status(400).json({ success: false, message: 'Không thể di chuyển vượt quá biên' });
  }

  // Hoán đổi vị trí
  const temp = db.ganttItems[index];
  db.ganttItems[index] = db.ganttItems[targetIndex];
  db.ganttItems[targetIndex] = temp;

  writeDb(db);

  return res.json({
    success: true,
    message: `Đã di chuyển công việc ${direction === 'up' ? 'lên trên' : 'xuống dưới'}`,
    data: db.ganttItems
  });
}

// Xóa công việc khỏi biểu đồ Gantt (đồng bộ xóa trong db.tasks)
export function deleteGanttItem(req, res) {
  const db = readDb();
  const { id } = req.params;

  const index = db.ganttItems.findIndex(g => g.id === id);
  if (index === -1) {
    return res.status(404).json({ success: false, message: 'Không tìm thấy công việc' });
  }

  const removed = db.ganttItems.splice(index, 1);

  // Đồng bộ xóa trong db.tasks
  if (db.tasks) {
    db.tasks = db.tasks.filter(t => t.ganttId !== id && t.title !== removed[0].title);
  }

  writeDb(db);

  return res.json({
    success: true,
    message: `Đã xóa công việc "${removed[0].title}" khỏi tiến độ và đồng bộ nhiệm vụ`,
    data: removed[0]
  });
}

import { readDb, writeDb } from '../models/db.js';
import { compareWbs } from './projectController.js';

/**
 * Controller Quản Lý Phân Công & Tăng Ca
 * Xử lý giao việc cho nhân sự, kiểm soát giờ làm việc chuẩn (8h/ngày),
 * và đăng ký ca làm thêm giờ (Overtime / OT) cho các công việc gấp.
 * ĐỒNG BỘ 2 CHIỀU HOÀN TOÀN VỚI BIỂU ĐỒ GANTT TIẾN ĐỘ DỰ ÁN.
 */

// Lấy danh sách nhiệm vụ và tăng ca
export function getTasks(req, res) {
  const db = readDb();
  return res.json({
    success: true,
    data: {
      tasks: db.tasks || [],
      overtimes: db.overtimes || []
    }
  });
}

// Tạo nhiệm vụ mới (Task Assignment) - ĐỒNG BỘ SANG GANTT CHART
export function createTask(req, res) {
  const db = readDb();
  const {
    projectId,
    projectName,
    phase,
    code,
    title,
    employeeId,
    startDate,
    endDate,
    estimatedDays,
    priority,
    notes
  } = req.body;

  if (!title || !employeeId) {
    return res.status(400).json({ success: false, message: 'Vui lòng nhập tên công việc và chọn người đảm nhận' });
  }

  // Tìm tên nhân sự
  const emp = db.employees.find(e => e.id === employeeId);
  const employeeName = emp ? emp.name : 'Chưa phân công';

  // Tìm tên dự án nếu có
  let projName = projectName;
  if (!projName && projectId) {
    const proj = db.projects.find(p => p.id === projectId);
    if (proj) projName = proj.name;
  }

  const days = Number(estimatedDays) || 1;
  const hours = days * 8; // 8 tiếng / ngày chuẩn

  // Sinh mã WBS tự động nếu chưa có
  let wbsCode = code ? String(code).trim() : '';
  if (!wbsCode) {
    let prefix = 'A';
    if (phase && phase.includes('B.')) prefix = 'B';
    else if (phase && phase.includes('C.')) prefix = 'C';
    else if (phase && phase.includes('L.')) prefix = 'L';

    // Đếm số công việc hiện có trong nhóm prefix
    const phaseItems = (db.ganttItems || []).filter(g => g.code.startsWith(prefix));
    wbsCode = `${prefix}1.${phaseItems.length + 1}`;
  }

  const newGanttId = `G-${Date.now()}`;

  const newTask = {
    id: `task-${Date.now()}`,
    ganttId: newGanttId,
    projectId: projectId || 'proj-1',
    projectName: projName || 'DỰ ÁN XÂY DỰNG TRUNG TÂM CÔNG NGHỆ APS VIỆT NAM',
    phase: phase || 'A. THIẾT KẾ XÂY DỰNG',
    code: wbsCode,
    title,
    employeeId,
    employeeName,
    startDate: startDate || new Date().toISOString().split('T')[0],
    endDate: endDate || new Date().toISOString().split('T')[0],
    estimatedHours: hours,
    estimatedDays: days,
    status: 'in_progress',
    speedStatus: 'on_time', // 'early', 'on_time', 'delayed'
    priority: priority || 'normal', // 'normal', 'high', 'urgent'
    progress: 0,
    notes: notes || ''
  };

  if (!db.tasks) db.tasks = [];
  db.tasks.push(newTask);

  // === ĐỒNG BỘ SANG TIẾN ĐỘ DỰ ÁN & BIỂU ĐỒ GANTT ===
  let color = '#0284c7';
  let unit = 'TK';
  if (phase && phase.includes('B.')) {
    color = '#ef4444';
    unit = 'PL';
  } else if (phase && phase.includes('C.')) {
    color = '#22c55e';
    unit = 'CDT';
  } else if (phase && phase.includes('L.')) {
    color = '#eab308';
    unit = 'VN';
  }

  // Tự động tìm công việc đứng trước để nối đường mũi tên FS
  let lastItemInPhase = null;
  for (let i = db.ganttItems.length - 1; i >= 0; i--) {
    if (db.ganttItems[i].code.startsWith(wbsCode.charAt(0))) {
      lastItemInPhase = db.ganttItems[i];
      break;
    }
  }

  const newGanttItem = {
    id: newGanttId,
    code: wbsCode,
    title,
    isGroup: false,
    color,
    unit,
    startDate: newTask.startDate,
    endDate: newTask.endDate,
    days: newTask.estimatedDays,
    assignee: employeeName,
    notes: notes || '',
    status: 'in_progress',
    speed: 'on_time',
    progress: 0,
    dependencies: lastItemInPhase ? [lastItemInPhase.id] : []
  };

  // Chèn vào Gantt theo thuật toán WBS (đúng vị trí cây phân cấp)
  let insertIdx = -1;
  for (let i = 0; i < db.ganttItems.length; i++) {
    if (compareWbs(db.ganttItems[i].code, newGanttItem.code) < 0) {
      insertIdx = i;
    }
  }
  if (insertIdx === -1) {
    db.ganttItems.unshift(newGanttItem);
  } else {
    db.ganttItems.splice(insertIdx + 1, 0, newGanttItem);
  }

  writeDb(db);

  return res.status(201).json({
    success: true,
    message: `Phân công nhiệm vụ thành công và đã đồng bộ sang biểu đồ Gantt (${wbsCode})`,
    data: newTask
  });
}

// Cập nhật trạng thái nhiệm vụ (đồng bộ sang Gantt)
export function updateTask(req, res) {
  const db = readDb();
  const { id } = req.params;
  const { status, progress, speedStatus, notes } = req.body;

  const task = db.tasks.find(t => t.id === id);
  if (!task) {
    return res.status(404).json({ success: false, message: 'Không tìm thấy nhiệm vụ' });
  }

  if (status !== undefined) task.status = status;
  if (progress !== undefined) task.progress = Number(progress);
  if (speedStatus !== undefined) task.speedStatus = speedStatus;
  if (notes !== undefined) task.notes = notes;

  if (task.progress === 100) {
    task.status = 'completed';
  }

  // Đồng bộ sang ganttItems tương ứng
  const gantt = (db.ganttItems || []).find(g => g.id === task.ganttId || g.title === task.title);
  if (gantt) {
    if (task.status !== undefined) gantt.status = task.status;
    if (task.progress !== undefined) gantt.progress = task.progress;
    if (task.speedStatus !== undefined) gantt.speed = task.speedStatus;
  }

  writeDb(db);

  return res.json({
    success: true,
    message: 'Cập nhật nhiệm vụ thành công và đã đồng bộ',
    data: task
  });
}

// Xóa nhiệm vụ (đồng bộ xóa trong Gantt)
export function deleteTask(req, res) {
  const db = readDb();
  const { id } = req.params;

  const index = db.tasks.findIndex(t => t.id === id);
  if (index === -1) {
    return res.status(404).json({ success: false, message: 'Không tìm thấy nhiệm vụ' });
  }

  const removed = db.tasks.splice(index, 1);

  // Đồng bộ xóa trong ganttItems
  if (db.ganttItems) {
    db.ganttItems = db.ganttItems.filter(g => g.id !== removed[0].ganttId && g.title !== removed[0].title);
  }

  writeDb(db);

  return res.json({
    success: true,
    message: 'Đã xóa nhiệm vụ và đồng bộ gỡ khỏi biểu đồ Gantt',
    data: removed[0]
  });
}

// Đăng ký ca làm việc tăng ca (Overtime / OT)
export function createOvertime(req, res) {
  const db = readDb();
  const { taskId, employeeId, hours, date, reason } = req.body;

  if (!employeeId || !hours) {
    return res.status(400).json({ success: false, message: 'Vui lòng chọn nhân viên và số giờ tăng ca' });
  }

  const emp = db.employees.find(e => e.id === employeeId);
  const task = taskId ? db.tasks.find(t => t.id === taskId) : null;

  const newOt = {
    id: `ot-${Date.now()}`,
    taskId: taskId || 'general',
    taskTitle: task ? task.title : 'Tăng ca đột xuất tại công trường',
    employeeId,
    employeeName: emp ? emp.name : 'Chưa xác định',
    hours: Number(hours),
    date: date || new Date().toISOString().split('T')[0],
    reason: reason || 'Hoàn thành công việc khẩn cấp',
    approvedBy: 'Trần Quốc Hưng (Chỉ huy trưởng)',
    status: 'approved'
  };

  db.overtimes.push(newOt);

  // Đồng bộ sang Gantt item tương ứng để hiện tag [+x h OT]
  if (taskId || task) {
    const gantt = (db.ganttItems || []).find(g => g.id === task?.ganttId || g.title === (task ? task.title : ''));
    if (gantt) {
      gantt.overtimeHours = (gantt.overtimeHours || 0) + Number(hours);
    }
  }

  writeDb(db);

  return res.status(201).json({
    success: true,
    message: `Đã đăng ký ${hours}h tăng ca cho ${newOt.employeeName}`,
    data: newOt
  });
}

