// Chiều cao mỗi dòng trong bảng & biểu đồ (khóa cứng pixel để không bị lệch)
const ROW_HEIGHT = 44;
const HEADER_HEIGHT = 52;
const BAR_HEIGHT = 24;

// Tính tọa độ vị trí (x, width, y) của từng thanh Gantt
const taskCoordinates = useMemo(() => {
  const coords = {};
  filteredGanttItems.forEach((item, index) => {
    const sDate = new Date(item.startDate);
    const eDate = new Date(item.endDate);

    const offsetDays = Math.max(0, (sDate - timelineStart) / (1000 * 60 * 60 * 24));
    const durationDays = Math.max(1, (eDate - sDate) / (1000 * 60 * 60 * 24) + 1);

    const x = offsetDays * pxPerDay;
    const width = Math.max(16, durationDays * pxPerDay);
    // Tọa độ Y chính xác căn giữa từng dòng 44px
    const y = HEADER_HEIGHT + index * ROW_HEIGHT + (ROW_HEIGHT - BAR_HEIGHT) / 2;
    const centerY = HEADER_HEIGHT + index * ROW_HEIGHT + ROW_HEIGHT / 2;

    coords[item.id] = {
      x,
      y,
      width,
      height: BAR_HEIGHT,
      endX: x + width,
      centerY,
      item
    };
  });
  return coords;
}, [filteredGanttItems, timelineStart, pxPerDay]);

// Tạo đường cong mũi tên phụ thuộc Finish-to-Start (FS) - TỰ ĐỘNG NỐI TỪ TASK TRƯỚC XUỐNG
const dependencyLines = useMemo(() => {
  const lines = [];
  filteredGanttItems.forEach((item, toIndex) => {
    let deps = Array.isArray(item.dependencies) ? [...item.dependencies] : [];

    // Nếu là công việc con và chưa có liên kết, tự động nối từ công việc đứng ngay trước đó
    if (deps.length === 0 && !item.isGroup && toIndex > 0) {
      const prevItem = filteredGanttItems[toIndex - 1];
      if (prevItem && !prevItem.isGroup) {
        deps = [prevItem.id];
      }
    }

    deps.forEach((depId) => {
      const from = taskCoordinates[depId];
      const to = taskCoordinates[item.id];
      if (from && to) {
        const startX = from.endX;
        const startY = from.centerY;
        const targetX = to.x;
        const targetY = to.centerY;

        let pathData = '';
        if (targetX >= startX) {
          const midX = startX + 12;
          pathData = `M ${startX} ${startY} L ${midX} ${startY} L ${midX} ${targetY} L ${targetX} ${targetY}`;
        } else {
          const loopX = startX + 10;
          const approachX = targetX - 10;
          const stepY = startY + (targetY > startY ? 14 : -14);
          pathData = `M ${startX} ${startY} L ${loopX} ${startY} L ${loopX} ${stepY} L ${approachX} ${stepY} L ${approachX} ${targetY} L ${targetX} ${targetY}`;
        }

        lines.push({
          key: `${depId}->${item.id}`,
          path: pathData,
          targetX,
          targetY
        });
      }
    });
  });
  return lines;
}, [filteredGanttItems, taskCoordinates]);

