13: /**
14:  * Phân tích mã WBS (VD: 'A1.3' -> { majorIdx: 0, segments: [1, 3] })
15:  */
16: export function parseWbsCode(code) {
17:   if (!code) return { majorIdx: 999, segments: [] };
18:   const cleaned = String(code).trim();
19:   const match = cleaned.match(/^([A-Za-z]+)(.*)$/);
20:   if (!match) return { majorIdx: 999, segments: [cleaned] };
21: 
22:   const letter = match[1].toUpperCase();
23:   const rest = match[2];
24: 
25:   let majorIdx = MAJOR_PHASE_ORDER.indexOf(letter);
26:   if (majorIdx === -1) majorIdx = 100 + letter.charCodeAt(0);
27: 
28:   const segments = rest
29:     ? rest
30:         .split('.')
31:         .map(s => {
32:           const num = parseInt(s, 10);
33:           return isNaN(num) ? s : num;
34:         })
35:     : [];
36: 
37:   return { majorIdx, segments };
38: }
