40: /**
41:  * So sánh 2 mã WBS để sắp xếp đúng thứ tự cây phân tầng
42:  * Ví dụ: A1 < A1.1 < A1.2 < A1.3 < A2 < A2.1 < L < B
43:  */
44: export function compareWbs(codeA, codeB) {
45:   const pa = parseWbsCode(codeA);
46:   const pb = parseWbsCode(codeB);
47: 
48:   // So sánh nhóm giai đoạn lớn trước (A trước L, L trước B, B trước C)
49:   if (pa.majorIdx !== pb.majorIdx) {
50:     return pa.majorIdx - pb.majorIdx;
51:   }
52: 
53:   // So sánh từng cấp số con bên trong
54:   const maxLen = Math.max(pa.segments.length, pb.segments.length);
55:   for (let i = 0; i < maxLen; i++) {
56:     const sa = pa.segments[i];
57:     const sb = pb.segments[i];
58: 
59:     if (sa === undefined) return -1; // Cấp cha ngắn hơn đứng trước (A1 đứng trước A1.1)
60:     if (sb === undefined) return 1;
61: 
62:     if (typeof sa === 'number' && typeof sb === 'number') {
63:       if (sa !== sb) return sa - sb;
64:     } else {
65:       const cmp = String(sa).localeCompare(String(sb));
66:       if (cmp !== 0) return cmp;
67:     }
68:   }
69: 
70:   return 0;
71: }
