{/* Khung cuộn ngang chứa cả Bảng bên trái + Biểu đồ bên phải */}
<div className="overflow-x-auto relative max-h-[700px] overflow-y-auto">
  <div className="flex" style={{ width: `${680 + ganttWidth}px`, minWidth: '100%' }}>

    {/* ================= KHUNG TRÁI: BẢNG DỮ LIỆU CÔNG VIỆC (ĐÓNG BĂNG FREEZE) ================= */}
    <div className="w-[680px] flex-shrink-0 sticky left-0 z-30 bg-white dark:bg-slate-900 border-r-2 border-slate-300 dark:border-slate-700 shadow-lg">

      {/* Header Bảng Bên Trái */}
      <div
        className="sticky top-0 z-40 bg-slate-100 dark:bg-slate-800 border-b border-slate-200 dark:border-slate-700 flex items-center text-xs font-bold text-slate-700 dark:text-slate-200 uppercase tracking-wider"
        style={{ height: `${HEADER_HEIGHT}px` }}
      >
        <div className="w-12 text-center py-2 px-1 border-r border-slate-200 dark:border-slate-700">STT</div>
        <div className="flex-1 py-2 px-3 border-r border-slate-200 dark:border-slate-700">CÔNG VIỆC TRONG DỰ ÁN</div>
        <div className="w-14 text-center py-2 px-1 border-r border-slate-200 dark:border-slate-700">ĐV</div>
        <div className="w-20 text-center py-2 px-1 border-r border-slate-200 dark:border-slate-700">BẮT ĐẦU</div>
        <div className="w-20 text-center py-2 px-1 border-r border-slate-200 dark:border-slate-700">KẾT THÚC</div>
        <div className="w-14 text-center py-2 px-1 border-r border-slate-200 dark:border-slate-700">NGÀY</div>
        <div className="w-24 py-2 px-2 border-r border-slate-200 dark:border-slate-700">GHI CHÚ</div>
        <div className="w-20 text-center py-2 px-1">THAO TÁC</div>
      </div>

      {/* Danh Sách Các Hàng Công Việc (Tên dự án và công việc nằm bên trái) */}
      <div className="divide-y divide-slate-100 dark:divide-slate-800">
        {filteredGanttItems.map((item) => {
          const isGroup = item.isGroup;
          const isHoliday = item.status === 'holiday';

          return (
            <div
              key={item.id}
              className={`flex items-center text-xs transition-colors hover:bg-slate-50 dark:hover:bg-slate-800/60 ${
                isGroup
                  ? 'font-bold bg-slate-50/80 dark:bg-slate-800/80 text-slate-900 dark:text-white'
                  : isHoliday
                  ? 'bg-amber-500/5 text-amber-800 dark:text-amber-200'
                  : 'text-slate-700 dark:text-slate-300'
              }`}
              style={{ height: `${ROW_HEIGHT}px` }}
            >
              {/* Cột STT */}
              <div className="w-12 text-center py-1 px-1 font-mono font-semibold border-r border-slate-100 dark:border-slate-800 truncate">
                {item.code}
              </div>

              {/* Cột Tên Công Việc (Có thụt dòng theo cấp A -> A1 -> A1.1) */}
              <div
                className="flex-1 py-1 px-3 border-r border-slate-100 dark:border-slate-800 truncate flex items-center gap-1.5"
                style={{
                  paddingLeft: item.code.includes('.')
                    ? '28px'
                    : item.code.length > 1
                    ? '18px'
                    : '12px'
                }}
              >
                {isGroup && (
                  <span
                    className="w-2.5 h-2.5 rounded-full flex-shrink-0"
                    style={{ backgroundColor: item.color }}
                  />
                )}
                <span className="truncate" title={item.title}>
                  {item.title}
                </span>
              </div>

              {/* Cột ĐV (Đơn vị thực hiện: TK, PL, CDT, NT, VN) */}
              <div className="w-14 text-center py-1 px-1 font-mono font-bold text-[11px] border-r border-slate-100 dark:border-slate-800 text-sky-600 dark:text-sky-400">
                {item.unit}
              </div>

              {/* Cột Bắt Đầu */}
              <div className="w-20 text-center py-1 px-1 text-[11px] border-r border-slate-100 dark:border-slate-800 text-slate-500">
                {item.startDate.slice(5).replace('-', '/')}
              </div>

              {/* Cột Kết Thúc */}
              <div className="w-20 text-center py-1 px-1 text-[11px] border-r border-slate-100 dark:border-slate-800 text-slate-500">
                {item.endDate.slice(5).replace('-', '/')}
              </div>

              {/* Cột Ngày (Duration) */}
              <div className="w-14 text-center py-1 px-1 font-bold text-[11px] border-r border-slate-100 dark:border-slate-800">
                {item.days}
              </div>

              {/* Cột Ghi Chú / GATE */}
              <div className="w-24 py-1 px-2 text-[10px] text-slate-400 truncate border-r border-slate-100 dark:border-slate-800" title={item.notes}>
                {item.notes || '-'}
              </div>

              {/* Cột Thao Tác (Di chuyển lên/xuống & Xóa) */}
              <div className="w-20 flex items-center justify-center gap-0.5 py-1 px-1">
                <button
                  onClick={() => moveGanttItem(item.id, 'up')}
                  className="p-1 rounded text-slate-400 hover:text-sky-500 hover:bg-sky-50 dark:hover:bg-slate-800 transition-colors"
                  title="Di chuyển lên trên"
                >
                  <ChevronUp className="w-3.5 h-3.5" />
                </button>
                <button
                  onClick={() => moveGanttItem(item.id, 'down')}
                  className="p-1 rounded text-slate-400 hover:text-sky-500 hover:bg-sky-50 dark:hover:bg-slate-800 transition-colors"
                  title="Di chuyển xuống dưới"
                >
                  <ChevronDown className="w-3.5 h-3.5" />
                </button>
                <button
                  onClick={() => deleteGanttItem(item.id)}
                  className="p-1 rounded text-slate-300 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-950/40 transition-colors"
                  title="Xóa công việc này"
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
              </div>

            </div>
          );
        })}
      </div>

    </div>

    {/* ================= KHUNG PHẢI: BIỂU ĐỒ GANTT NẰM BÊN PHẢI (SVG TƯƠNG TÁC) ================= */}
    <div className="relative flex-1 bg-slate-50/50 dark:bg-slate-950/50" style={{ width: `${ganttWidth}px` }}>

      {/* Header Tháng & Tuần của Biểu Đồ Gantt */}
      <div
        className="sticky top-0 z-20 bg-slate-100 dark:bg-slate-800 border-b border-slate-200 dark:border-slate-700 flex"
        style={{ height: `${HEADER_HEIGHT}px`, width: `${ganttWidth}px` }}
      >
        {monthColumns.map((col, idx) => (
          <div
            key={idx}
            className="border-r border-slate-200 dark:border-slate-700 flex flex-col justify-center items-center px-1 text-center select-none"
            style={{ width: `${col.width}px` }}
          >
            <span className="font-extrabold text-xs text-sky-600 dark:text-sky-400">
              {col.label}
            </span>
            <span className="text-[10px] text-slate-400 font-mono">
              Tuần 1-4
            </span>
          </div>
        ))}
      </div>

      {/* Lưới Nền (Grid Lines) & Dải Ruy-băng Nghỉ Lễ Việt Nam */}
      <div className="absolute inset-0 top-[50px] pointer-events-none flex" style={{ width: `${ganttWidth}px` }}>
        {monthColumns.map((col, idx) => (
          <div
            key={idx}
            className="border-r border-slate-200/40 dark:border-slate-800/40 h-full"
            style={{ width: `${col.width}px` }}
          />
        ))}
      </div>

      {/* KHUNG VẼ THANH GANTT & ĐƯỜNG MŨI TÊN FS BẰNG SVG CHÍNH XÁC */}
      <svg
        width={ganttWidth}
        height={HEADER_HEIGHT + filteredGanttItems.length * ROW_HEIGHT + 20}
        className="relative z-10"
      >
        <defs>
          {/* Mũi tên đầu đường phụ thuộc Finish-to-Start */}
          <marker
            id="arrowhead"
            markerWidth="8"
            markerHeight="8"
            refX="6"
            refY="3"
            orient="auto"
          >
            <path d="M0,0 L0,6 L6,3 z" fill="#0284c7" />
          </marker>

          {/* Gradient cho các thanh bar */}
          <linearGradient id="grad-sky" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="#0284c7" />
            <stop offset="100%" stopColor="#38bdf8" />
          </linearGradient>
          <linearGradient id="grad-amber" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="#d97706" />
            <stop offset="100%" stopColor="#fbbf24" />
          </linearGradient>
          <linearGradient id="grad-red" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="#b91c1c" />
            <stop offset="100%" stopColor="#ef4444" />
          </linearGradient>
          <linearGradient id="grad-green" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="#15803d" />
            <stop offset="100%" stopColor="#22c55e" />
          </linearGradient>
        </defs>

        {/* 1. Vẽ các đường kẻ ngang phân tách từng dòng */}
        {filteredGanttItems.map((_, idx) => (
          <line
            key={idx}
            x1="0"
            y1={HEADER_HEIGHT + idx * ROW_HEIGHT}
            x2={ganttWidth}
            y2={HEADER_HEIGHT + idx * ROW_HEIGHT}
            stroke="#e2e8f0"
            strokeWidth="1"
            className="dark:stroke-slate-800/60"
          />
        ))}

        {/* 2. HIỂN THỊ MŨI TÊN KẺ XUỐNG CÔNG VIỆC TIẾP THEO TRONG DỰ ÁN (FS Dependency) */}
        {dependencyLines.map((line) => (
          <path
            key={line.key}
            d={line.path}
            fill="none"
            stroke="#0284c7"
            strokeWidth="1.8"
            strokeDasharray="4 2"
            markerEnd="url(#arrowhead)"
            className="transition-all hover:stroke-sky-400"
          />
        ))}

        {/* 3. Vẽ các thanh tiến độ Gantt Bar */}
        {filteredGanttItems.map((item) => {
          const coord = taskCoordinates[item.id];
          if (!coord) return null;

          const isGroup = item.isGroup;
          const isHoliday = item.status === 'holiday';

          // Chọn màu gradient
          let fillColor = 'url(#grad-sky)';
          if (item.color === '#eab308' || isHoliday) fillColor = 'url(#grad-amber)';
          if (item.color === '#dc2626') fillColor = 'url(#grad-red)';
          if (item.color === '#16a34a') fillColor = 'url(#grad-green)';

          return (
            <g key={item.id} className="cursor-pointer group">

              {/* Dải ruy băng mờ kéo ngang cho ngày lễ */}
              {isHoliday && (
                <rect
                  x={coord.x}
                  y={HEADER_HEIGHT}
                  width={coord.width}
                  height={filteredGanttItems.length * ROW_HEIGHT}
                  fill="#fef08a"
                  fillOpacity="0.12"
                />
              )}

              {/* Thanh Gantt chính */}
              <rect
                x={coord.x}
                y={coord.y}
                width={coord.width}
                height={coord.height}
                rx="8"
                ry="8"
                fill={fillColor}
                className="transition-all hover:opacity-90 shadow-sm"
                filter="drop-shadow(0 2px 4px rgba(0,0,0,0.12))"
              />

              {/* Nhãn trên thanh hoặc cạnh thanh: Tên người đảm nhận, thời gian, tăng ca */}
              <text
                x={coord.endX + 8}
                y={coord.centerY + 4}
                fill="#64748b"
                fontSize="11"
                fontWeight="600"
                className="dark:fill-slate-300 select-none pointer-events-none"
              >
                {item.assignee} ({item.days} ngày)
                {item.overtimeHours && (
                  <tspan fill="#f59e0b" fontWeight="bold"> [+{item.overtimeHours}h OT]</tspan>
                )}
                {item.speed === 'early' && (
                  <tspan fill="#10b981"> [Sớm]</tspan>
                )}
                {item.speed === 'delayed' && (
                  <tspan fill="#ef4444" fontWeight="bold"> [Chậm]</tspan>
                )}
              </text>

              {/* Chữ hiển thị bên trong thanh nếu đủ rộng */}
              {coord.width > 60 && (
                <text
                  x={coord.x + 8}
                  y={coord.centerY + 4}
                  fill="#ffffff"
                  fontSize="10"
                  fontWeight="bold"
                  className="select-none pointer-events-none truncate"
                >
                  {item.code} {coord.width > 120 ? `- ${item.days}d` : ''}
                </text>
              )}

            </g>
          );
        })}

      </svg>

    </div>

  </div>
</div>

