let cachedDb = null;
const SEED_FILE = path.join(__dirname, '../../data/seed.json');

// Đọc dữ liệu từ file db.json (có cache bộ nhớ & dự phòng seed.json an toàn)
export function readDb() {
  try {
    if (fs.existsSync(DB_FILE)) {
      const raw = fs.readFileSync(DB_FILE, 'utf-8');
      if (raw && raw.trim().length > 10) {
        const parsed = JSON.parse(raw);
        if (parsed && Array.isArray(parsed.projects) && Array.isArray(parsed.ganttItems) && parsed.ganttItems.length > 0) {
          cachedDb = parsed;
          return parsed;
        }
      }
    }
  } catch (error) {
    console.error('Lỗi khi đọc file db.json:', error.message);
  }

  // Sử dụng cache trong RAM nếu có
  if (cachedDb && cachedDb.ganttItems && cachedDb.ganttItems.length > 0) {
    return cachedDb;
  }

  // Fallback an toàn tới seed.json nếu db.json trống hoặc bị lỗi
  try {
    if (fs.existsSync(SEED_FILE)) {
      const rawSeed = fs.readFileSync(SEED_FILE, 'utf-8');
      const seedObj = JSON.parse(rawSeed);
      cachedDb = seedObj;
      fs.writeFileSync(DB_FILE, JSON.stringify(seedObj, null, 2), 'utf-8');
      return seedObj;
    }
  } catch (seedErr) {
    console.error('Lỗi khi nạp seed.json:', seedErr.message);
  }

  return cachedDb || { projects: [], employees: [], tasks: [], overtimes: [], ganttItems: [] };
}

// Lưu dữ liệu vào file db.json an toàn
export function writeDb(data) {
  try {
    if (!data) return false;
    // Bảo vệ không để mảng ganttItems hoặc projects bị xóa rỗng vô ý
    if ((!data.ganttItems || data.ganttItems.length === 0) && cachedDb && cachedDb.ganttItems && cachedDb.ganttItems.length > 0) {
      data.ganttItems = cachedDb.ganttItems;
    }
    if ((!data.projects || data.projects.length === 0) && cachedDb && cachedDb.projects && cachedDb.projects.length > 0) {
      data.projects = cachedDb.projects;
    }

    cachedDb = data;
    fs.writeFileSync(DB_FILE, JSON.stringify(data, null, 2), 'utf-8');
    return true;
  } catch (error) {
    console.error('Lỗi khi ghi file db.json:', error.message);
    return false;
  }
}

